import { EventEmitter } from 'events';
import * as net from 'net';
import * as crypto from 'crypto';

interface FirmwareConfig {
  deviceId: string;
  updatePort: number;
  maxPayloadSize: number;
  shutdownTimeout: number;
}

class MemoryRegion {
  private buffer: Buffer;
  private executable: boolean;
  private offset: number;

  constructor(size: number, executable: boolean = false) {
    this.buffer = Buffer.alloc(size);
    this.executable = executable;
    this.offset = 0;
  }

  write(data: Buffer, position?: number): number {
    const writePos = position !== undefined ? position : this.offset;
    const bytesWritten = data.copy(this.buffer, writePos);
    if (position === undefined) {
      this.offset += bytesWritten;
    }
    return bytesWritten;
  }

  read(start: number, length: number): Buffer {
    return this.buffer.slice(start, start + length);
  }

  getOffset(): number {
    return this.offset;
  }

  reset(): void {
    this.offset = 0;
  }

  isExecutable(): boolean {
    return this.executable;
  }

  size(): number {
    return this.buffer.length;
  }
}

class ShutdownHandler {
  private callbacks: Array<{ priority: number; fn: () => Promise<void>; label: string }>;
  private returnAddressStack: Buffer;
  private stackPointer: number;

  constructor() {
    this.callbacks = [];
    this.returnAddressStack = Buffer.alloc(256);
    this.stackPointer = 0;
  }

  register(priority: number, fn: () => Promise<void>, label: string): void {
    this.callbacks.push({ priority, fn, label });
    this.callbacks.sort((a, b) => b.priority - a.priority);
  }

  pushReturnContext(addr: Buffer): void {
    addr.copy(this.returnAddressStack, this.stackPointer);
    this.stackPointer += addr.length;
  }

  popReturnContext(size: number): Buffer {
    this.stackPointer -= size;
    return this.returnAddressStack.slice(this.stackPointer, this.stackPointer + size);
  }

  async executeShutdown(): Promise<void> {
    for (const cb of this.callbacks) {
      console.log(`[shutdown] executing: ${cb.label}`);
      await cb.fn();
    }
  }
}

class IoTFirmwareDevice extends EventEmitter {
  private config: FirmwareConfig;
  private dataRegion: MemoryRegion;
  private codeRegion: MemoryRegion;
  private shutdownHandler: ShutdownHandler;
  private server: net.Server | null = null;
  private isRunning: boolean = false;

  constructor(config: FirmwareConfig) {
    super();
    this.config = config;
    this.dataRegion = new MemoryRegion(4096, false);
    this.codeRegion = new MemoryRegion(2048, true);
    this.shutdownHandler = new ShutdownHandler();
    this.setupShutdownHandlers();
  }

  private setupShutdownHandlers(): void {
    this.shutdownHandler.register(100, async () => {
      this.isRunning = false;
    }, 'stop-services');

    this.shutdownHandler.register(50, async () => {
      if (this.server) {
        this.server.close();
      }
    }, 'close-connections');

    this.shutdownHandler.register(10, async () => {
      this.dataRegion.reset();
      this.codeRegion.reset();
    }, 'clear-memory');
  }

  private validateFirmwarePacket(data: Buffer): { valid: boolean; payload: Buffer; targetRegion: string } {
    if (data.length < 16) {
      return { valid: false, payload: Buffer.alloc(0), targetRegion: '' };
    }

    const magic = data.readUInt32BE(0);
    if (magic !== 0xF1RMWARE) {
      return { valid: false, payload: Buffer.alloc(0), targetRegion: '' };
    }

    const hmac = data.slice(4, 12);
    const regionFlag = data.readUInt8(12);
    const payloadLength = data.readUInt16BE(13);
    const payload = data.slice(15, 15 + payloadLength);

    const expectedHmac = crypto.createHmac('sha256', 'device-key-' + this.config.deviceId)
      .update(data.slice(12))
      .digest()
      .slice(0, 8);

    if (!crypto.timingSafeEqual(hmac, expectedHmac)) {
      return { valid: false, payload: Buffer.alloc(0), targetRegion: '' };
    }

    const targetRegion = regionFlag === 0x01 ? 'code' : 'data';

    return { valid: true, payload, targetRegion };
  }

  private processFirmwareUpdate(data: Buffer): void {
    const { valid, payload, targetRegion } = this.validateFirmwarePacket(data);

    if (!valid) {
      this.emit('update-rejected', 'invalid packet');
      return;
    }

    if (payload.length > this.config.maxPayloadSize) {
      this.emit('update-rejected', 'payload too large');
      return;
    }

    const returnAddr = Buffer.alloc(8);
    returnAddr.writeUInt32BE(targetRegion === 'code' ? 0x00401000 : 0x00801000, 0);
    returnAddr.writeUInt32BE(payload.length, 4);
    this.shutdownHandler.pushReturnContext(returnAddr);

    if (targetRegion === 'code') {
      this.codeRegion.write(payload);
      this.emit('code-updated', this.codeRegion.getOffset());
    } else {
      this.dataRegion.write(payload);
      this.emit('data-updated', this.dataRegion.getOffset());
    }
  }

  private handleGracefulShutdown(triggerData?: Buffer): void {
    if (triggerData && triggerData.length >= 8) {
      const contextSize = triggerData.readUInt32BE(0);
      const iterations = triggerData.readUInt32BE(4);

      for (let i = 0; i < iterations; i++) {
        const ctx = this.shutdownHandler.popReturnContext(contextSize);
        const addr = ctx.readUInt32BE(0);
        const len = ctx.readUInt32BE(4);

        if (this.codeRegion.isExecutable()) {
          const gadget = this.codeRegion.read(addr & 0x7FF, len & 0xFF);
          this.emit('gadget-executed', gadget);
        }
      }
    }

    this.shutdownHandler.executeShutdown();
  }

  start(): void {
    this.isRunning = true;
    this.server = net.createServer((socket) => {
      socket.on('data', (data) => {
        const command = data.readUInt8(0);
        switch (command) {
          case 0x01:
            this.processFirmwareUpdate(data.slice(1));
            break;
          case 0x02:
            this.handleGracefulShutdown(data.slice(1));
            break;
          case 0xFF:
            this.handleGracefulShutdown();
            break;
        }
      });
    });

    this.server.listen(this.config.updatePort, () => {
      console.log(`[firmware] device ${this.config.deviceId} listening on port ${this.config.updatePort}`);
    });

    process.on('SIGTERM', () => this.handleGracefulShutdown());
    process.on('SIGINT', () => this.handleGracefulShutdown());
  }
}

const device = new IoTFirmwareDevice({
  deviceId: 'sensor-node-7a3f',
  updatePort: 8443,
  maxPayloadSize: 1024,
  shutdownTimeout: 5000
